package com.cdac.cssip.meeting.controller;import com.cdac.cssip.common.security.AuthenticatedUser;import com.cdac.cssip.meeting.dto.MeetingDtos.*;import com.cdac.cssip.meeting.service.MeetingService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/meetings") @RequiredArgsConstructor public class MeetingController{private final MeetingService s;@PostMapping @PreAuthorize("hasRole('STAFF')")public MeetingView create(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CreateMeetingRequest r){return s.create(u.userId(),r);}@PutMapping("/{id}") @PreAuthorize("hasRole('STAFF')")public MeetingView update(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id,@Valid @RequestBody UpdateMeetingRequest r){return s.update(u.userId(),id,r);}@PutMapping("/{id}/cancel") @PreAuthorize("hasRole('STAFF')")public MeetingView cancel(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id,@Valid @RequestBody CancelRequest r){return s.cancel(u.userId(),id,r.reason());}@GetMapping("/staff") @PreAuthorize("hasRole('STAFF')")public List<MeetingView> staff(@AuthenticationPrincipal AuthenticatedUser u){return s.staff(u.userId());}@GetMapping("/student") @PreAuthorize("hasRole('STUDENT')")public List<MeetingView> student(@AuthenticationPrincipal AuthenticatedUser u){return s.student(u.userId());}}
